// Piecewise-polynomial SPH kernels and their precomputed kernel-integral coefficients.
//
// Everything numeric in KernelSpec is generated by tools/kernel_tables/gen_cpp.py (exactly derived
// from the kernel definitions, see tools/kernel_tables/README.md) into src/kernel_spec_data.cpp --
// do not edit that file by hand.
//
// Conventions (thesis appendix A): the kernel is W(r) = A_3 / H^3 * w(q), q = r / H, with support
// radius H, w = 0 for q >= 1.  The q axis is split into n pieces by the breakpoints c_1 < ... < c_n = 1;
// "regions" are numbered 1..n for the pieces and n+1 for q > 1.  Arrays below are indexed by
// region - 1.
#pragma once

#include <string>
#include <vector>

namespace kiwi {

struct KernelSpec {
    static constexpr int MAX_REGIONS = 4; // pieces + 1 (quartic and quintic splines have 3 pieces)
    static constexpr int NI = 15;         // i = 1, 0, -1, ..., -13  ->  index 1 - i
    static constexpr int NB = 16;         // powers of q0 in B_j: 0..15

    const char* key;     // "M4", "M5", "M6", "WC2", "WC4", "WC6"
    const char* name;    // "Cubic spline", ...
    int nreg;            // number of regions (pieces + 1)
    double c[MAX_REGIONS];   // breakpoints c_1..c_n in units of H (c[nreg-2] == 1)
    double A2_pi, A3_pi; // normalisation constants times pi: A_d = A_d_pi / pi
    double radkern;      // support radius H in units of the snapshot smoothing length h (SPLASH/Phantom convention)

    // 3D vertex-pyramid coefficients: d I_P / d phi = A_3 * [ sum_{i != 0} a[k][1-i] mu^i q0^(1-i)
    //                                                         + B[j][k](q0) ]    (mu = r0 / r, q0 = r0 / H)
    // for a vertex in region k and a wall foot (r0) in region j <= k.
    double a[MAX_REGIONS][NI];
    double B[MAX_REGIONS][MAX_REGIONS][NB];
};

// Looks a kernel up by key (case-insensitive) or by common alias ("cubic", "quartic", "quintic",
// "wendland_c2", ...).  Throws std::invalid_argument for an unknown name.
const KernelSpec& get_kernel(const std::string& name);

// All kernels, in the order M4, M5, M6, WC2, WC4, WC6.
const std::vector<const KernelSpec*>& all_kernels();

} // namespace kiwi
